fn test_an_ocr_answer_holds_words_with_their_text() {
    let c: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let at: i32 = an_ocr(c, 3);
    let w0: i32 = an_ocr_word(c, at, 10, 20, 300, 40, 912, 0, 1);
    an_ocr_cp(c, w0, 72);
    an_ocr_cp(c, w0, 105);
    let w1: i32 = an_ocr_word(c, at, 400, 20, 50, 40, 870, 0, 1);
    an_ocr_cp(c, w1, 128512);
    an_ocr_end(c, at);
    crate::testport::assert_eq(an_ocr_count(c, at), 2, "two words");
    crate::testport::assert_eq(an_ocr_first(c, at), 5, "the first word follows the count");
    crate::testport::assert_eq(an_ocr_first(c, at), w0, "and is w0");
    crate::testport::assert_eq(aw_get(c, w0, aw_x()), 10, "x");
    crate::testport::assert_eq(aw_get(c, w0, aw_conf()), 912, "confidence x10");
    crate::testport::assert_eq(aw_get(c, w0, aw_len()), 2, "two code points");
    crate::testport::assert_eq(aw_cp(c, w0, 1), 105, "i");
    crate::testport::assert_eq(aw_next(c, w0), w1, "the next word");
    crate::testport::assert_eq(aw_cp(c, w1, 0), 128512, "a code point outside the BMP is one cell");
    crate::testport::assert_eq(aw_next(c, w1), crate::port::cells_len(c), "and the last ends the record");
    crate::testport::assert_eq(rec_len(c, at), crate::port::cells_len(c), "the record's length covers them");
}
#[test]
fn test_a_record_walk_refuses_what_is_malformed() {
    let c: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let d: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let e: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let f: &mut crate::port::Cells = &mut crate::port::Cells::new();
    rq_render(c, 1, 0, 0, 72, 0);
    rq_render(c, 2, 0, 1, 72, 0);
    crate::testport::assert_eq(rec_check(c, 1, 3), 0, "well formed");
    rq_render(c, 2, 0, 2, 72, 0);
    crate::testport::assert_eq(rec_check(c, 1, 3), 4, "a repeated id");
    rq_bytes(d, 1, 0, 0, 1);
    crate::testport::assert_eq(rec_check(d, 1, 3), 2, "a bytes request is not one kin may make");
    crate::testport::assert_eq(rec_check(d, 1, 4), 0, "though it is a record");
    rq_render(e, 0, 0, 0, 72, 0);
    crate::testport::assert_eq(rec_check(e, 1, 3), 3, "an id of 0");
    crate::port::cells_push(f, 9);
    crate::port::cells_push(f, 1);
    crate::port::cells_push(f, 1);
    crate::testport::assert_eq(rec_check(f, 1, 3), 1, "a length past the end");
    crate::testport::assert_eq(rec_count(f), -1, "is not a run of records");
    crate::testport::assert_eq(rec_count(&mut crate::port::Cells::new()), 0, "nothing is zero records");
    crate::testport::assert_eq(rec_find(&mut crate::port::Cells::new(), 1), -1, "and finds nothing");
}
