#[test]
fn test_the_probe_asks_in_two_rounds_and_then_writes_evidence() {
    let s: &crate::port::Src = &crate::port::src_of_blob(&crate::testport::text_blob("0123456789abcdef")[..]);
    let an: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let rq: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let et: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let t: &mut String = &mut crate::port::new_text();
    crate::testport::assert_eq(pt_unit(s, an, rq, et, t), 1, "round 0 asks");
    crate::testport::assert_eq(rec_count(rq), 2, "for two things");
    crate::testport::assert_eq(rec_check(rq, 1, 3), 0, "well formed");
    crate::testport::assert_eq(rec_id(rq, 0), 1, "the render is id 1");
    crate::testport::assert_eq(rec_kind(rq, 0), 1, "a render");
    let second: i32 = rec_next(rq, 0);
    crate::testport::assert_eq(rec_kind(rq, second), 2, "and a decode");
    an_render(an, 1, 64, 48, 1, 300);
    an_decode(an, 2, 32, 16, 3, 7200, 0, 1);
    crate::port::cells_drop(rq, 0);
    crate::testport::assert_eq(pt_unit(s, an, rq, et, t), 1, "round 1 asks");
    crate::testport::assert_eq(rec_count(rq), 2, "for two OCRs");
    crate::testport::assert_eq(rec_id(rq, 0), 3, "id 3");
    crate::testport::assert_eq(rq_arg(rq, 0, 0), 1, "of the render's bitmap");
    let second4: i32 = rec_next(rq, 0);
    crate::testport::assert_eq(rec_id(rq, second4), 4, "id 4");
    crate::testport::assert_eq(rq_arg(rq, second4, 0), 2, "of the decode's bitmap");
    let o3: i32 = an_ocr(an, 3);
    let w: i32 = an_ocr_word(an, o3, 6, 3, 40, 9, 911, 0, 0);
    an_ocr_cp(an, w, 72);
    an_ocr_cp(an, w, 105);
    an_ocr_end(an, o3);
    an_fail(an, 3, 4, 1);
    crate::port::cells_drop(rq, 0);
    crate::testport::assert_eq(pt_unit(s, an, rq, et, t), 0, "round 2 is done");
    crate::testport::assert_eq(crate::port::cells_len(rq), 0, "and asks for nothing");
}
